1	/**
2	 * Changes that take effect straight away. A plan or seat change on a date gives
3	 * back what is unused of the current terms and charges the new terms for the rest
4	 * of the period. A cancellation only gives back the unused time.
5	 */
6	
7	import { seatCharge } from '../catalog/plans.mjs';
8	import { prorateAmount } from './proration.mjs';
9	import { assertChangeAllowed, createRecord, updateRecord } from './record.mjs';
10	import { discountFor, nextCouponUses } from './renewal.mjs';
11	import { chargeLineIndex, reversalLink, segmentFor, unusedCredit } from './segments.mjs';
12	
13	function resolveTerms(record, change) {
14	  const plan = change.plan ?? record.plan;
15	  const seats = change.seats ?? record.seats;
16	  assertChangeAllowed(record, plan, seats);
17	  return { plan, seats };
18	}
19	
20	/**
21	 * The invoice input for a change.
22	 *
23	 * @param {object} record the subscription
24	 * @param {object} change { date, plan?, seats? }
25	 * @param {object} context { number, taxRateBps, reversedNet }
26	 */
27	export function draftPlanChange(record, change, context) {
28	  const { date } = change;
29	  const { number, taxRateBps, reversedNet } = context;
30	  const { plan, seats } = resolveTerms(record, change);
31	  const { period } = record;
32	  const servicePeriod = { start: date, end: period.end };
33	  const label = `(${date} to ${period.end})`;
34	
35	  const charge = prorateAmount(seatCharge(plan, record.currency, seats), period, date);
36	  const credit = unusedCredit(record, date, reversedNet);
37	
38	  const lines = [];
39	  if (credit > 0) {
40	    lines.push({
41	      description: `Unused ${record.plan.name} ${label}`,
42	      unitAmount: -credit,
43	      taxRateBps,
44	      period: servicePeriod,
45	      reverses: reversalLink(record.segment),
46	    });
47	  }
48	  lines.push({
49	    description: `${plan.name} ${label}`,
50	    unitAmount: charge,
51	    taxRateBps,
52	    period: servicePeriod,
53	  });
54	
55	  return {
56	    number,
57	    customerId: record.customerId,
58	    subscriptionId: record.id,
59	    currency: record.currency,
60	    issueDate: date,
61	    discount: discountFor(record, period.index),
62	    lines,
63	  };
64	}
65	
66	/** The record once the change's invoice has gone out. */
67	export function applyPlanChange(record, change, invoice) {
68	  const { plan, seats } = resolveTerms(record, change);
69	  const index = chargeLineIndex(invoice);
70	  const changes = {
71	    couponUses: nextCouponUses(record),
72	    plan,
73	    seats,
74	    segment: segmentFor(invoice, index, change.date, record.period.end),
75	  };
76	  // The new terms go through the same checks as a new subscription.
77	  return createRecord({ ...record, ...changes });
78	}
79	
80	/**
81	 * The invoice input that gives back the unused time, or null when there is
82	 * nothing to give back.
83	 */
84	export function draftCancellation(record, date, context) {
85	  const { number, taxRateBps, reversedNet } = context;
86	  const credit = unusedCredit(record, date, reversedNet);
87	  if (credit === 0) return null;
88	  return {
89	    number,
90	    customerId: record.customerId,
91	    subscriptionId: record.id,
92	    currency: record.currency,
93	    issueDate: date,
94	    lines: [
95	      {
96	        description: `Unused ${record.plan.name} (${date} to ${record.period.end})`,
97	        unitAmount: -credit,
98	        taxRateBps,
