26	    id,
27	    customerId,
28	    plan,
29	    currency,
30	    anchor,
31	    intervalMonths = 1,
32	    seats = 1,
33	    region = null,
34	    coupon = null,
35	    status = 'active',
36	    period = null,
37	    segment = null,
38	    endedOn = null,
39	    couponUses = 0,
