66	/** A copy of the record with the given fields changed. */
67	export function updateRecord(record, changes) {
68	  return Object.freeze({ ...record, ...changes });
69	}
70	
71	/** Throws unless the new terms could be sold on this subscription. */
72	export function assertChangeAllowed(record, plan, seats) {
