1	/**
2	 * Invoices: turns priced lines into a discounted, taxed document whose numbers
3	 * are all integer minor units of a single currency.
4	 */
5	
6	import { assertCurrency } from '../core/currencies.mjs';
7	import { parseIsoDate } from '../core/dates.mjs';
8	import { assertMinorUnits } from '../core/money.mjs';
9	import { assertBasisPoints, assertNonEmptyArray, assertPositiveInteger, assertText } from '../core/validate.mjs';
10	import { runPipeline } from './pipeline.mjs';
11	
12	/**
13	 * A line is { description, unitAmount, quantity?, taxRateBps?, period?, reverses? }.
14	 *
15	 * `period` is the time the line pays for, { start, end }, end exclusive.
16	 * `reverses` marks a credit line as giving back part of an earlier charge, and
17	 * points at it: { invoiceNumber, lineIndex }.
18	 */
19	export function normalizeLine(input, position) {
20	  const {
21	    description,
22	    unitAmount,
23	    quantity = 1,
24	    taxRateBps = 0,
25	    period = null,
26	    reverses = null,
27	  } = input;
28	  assertText(description, `Line ${position} description`);
29	  assertMinorUnits(unitAmount, `Line ${position} unitAmount`);
30	  assertPositiveInteger(quantity, `Line ${position} quantity`);
31	  assertBasisPoints(taxRateBps, `Line ${position} tax rate`);
32	  const amount = unitAmount * quantity;
33	  assertMinorUnits(amount, `Line ${position} amount`);
34	  return { description, unitAmount, quantity, amount, taxRateBps, period, reverses };
35	}
36	
37	/**
38	 * Builds an invoice.
39	 *
40	 * @param {object} input
41	 * @param {string} input.number invoice number
42	 * @param {string} input.customerId
43	 * @param {string} input.currency
44	 * @param {string} input.issueDate ISO date
45	 * @param {object[]} input.lines see normalizeLine
46	 * @param {object} [input.discount] { percentBps } or { fixed }
47	 * @param {number} [input.accountCredit] credit the customer holds on account
48	 * @param {string} [input.subscriptionId]
49	 */
50	export function buildInvoice(input) {
51	  const {
52	    number,
53	    customerId,
54	    currency,
55	    issueDate,
56	    lines,
57	    discount = null,
58	    accountCredit = 0,
59	    subscriptionId = null,
60	  } = input;
61	  assertCurrency(currency);
62	  parseIsoDate(issueDate);
63	  assertText(number, 'Invoice number');
64	  assertNonEmptyArray(lines, 'Invoice lines');
65	  assertMinorUnits(accountCredit, 'account credit');
66	  if (accountCredit < 0) throw new RangeError('Account credit cannot be negative');
67	
68	  const finished = runPipeline({
69	    lines: lines.map(normalizeLine),
70	    discount,
71	    accountCredit,
72	  });
73	
74	  return {
75	    number,
76	    customerId,
77	    subscriptionId,
78	    currency,
79	    issueDate,
80	    lines: finished.lines,
81	    taxSummary: finished.taxSummary,
82	    subtotal: finished.subtotal,
83	    discountTotal: finished.discountTotal,
84	    netTotal: finished.netTotal,
85	    taxTotal: finished.taxTotal,
86	    total: finished.total,
87	    creditApplied: finished.creditApplied,
88	    amountDue: finished.amountDue,
89	  };
90	}
