1	/**
2	 * Overdue invoices. Invoices fall due a fixed number of days after they are
3	 * issued, an open invoice moves through reminder stages as it gets older, and the
4	 * aging report sorts open balances by how overdue they are.
5	 */
6	
7	import { addDays, compareDates, daysBetween } from '../core/dates.mjs';
8	
9	export const DEFAULT_TERMS_DAYS = 30;
10	
11	const STAGES = Object.freeze([
12	  { name: 'final-notice', after: 60 },
13	  { name: 'second-reminder', after: 30 },
14	  { name: 'first-reminder', after: 7 },
15	  { name: 'overdue', after: 0 },
16	]);
17	
18	export function dueDate(invoice, termsDays = DEFAULT_TERMS_DAYS) {
19	  return addDays(invoice.issueDate, termsDays);
20	}
21	
22	export function daysOverdue(invoice, asOf, termsDays = DEFAULT_TERMS_DAYS) {
23	  return daysBetween(dueDate(invoice, termsDays), asOf);
24	}
25	
26	/** The reminder stage an invoice has reached, or null if it is not overdue. */
27	export function reminderStage(invoice, asOf, termsDays = DEFAULT_TERMS_DAYS) {
28	  if (compareDates(asOf, dueDate(invoice, termsDays)) <= 0) return null;
29	  const overdue = daysOverdue(invoice, asOf, termsDays);
30	  return STAGES.find((stage) => overdue > stage.after)?.name ?? null;
31	}
32	
33	/**
34	 * Open invoices that need a reminder, oldest first.
35	 *
36	 * @param {object[]} invoices
37	 * @param {(invoice: object) => number} balanceOf
38	 * @param {string} asOf
39	 */
40	export function dunningQueue(invoices, balanceOf, asOf, termsDays = DEFAULT_TERMS_DAYS) {
41	  return invoices
42	    .map((invoice) => ({
43	      number: invoice.number,
44	      customerId: invoice.customerId,
45	      currency: invoice.currency,
46	      balance: balanceOf(invoice),
47	      stage: reminderStage(invoice, asOf, termsDays),
48	      overdueDays: daysOverdue(invoice, asOf, termsDays),
49	    }))
50	    .filter((entry) => entry.balance > 0 && entry.stage !== null)
51	    .sort((a, b) => b.overdueDays - a.overdueDays || a.number.localeCompare(b.number));
52	}
53	
54	const BUCKETS = Object.freeze([
55	  { name: 'current', upTo: 0 },
56	  { name: '1-30', upTo: 30 },
57	  { name: '31-60', upTo: 60 },
58	  { name: '61+', upTo: Infinity },
59	]);
60	
61	function bucketFor(overdue) {
62	  return BUCKETS.find((bucket) => overdue <= bucket.upTo).name;
63	}
64	
65	export function agingReport({ invoices, balanceOf, asOf, currency, termsDays = DEFAULT_TERMS_DAYS }) {
66	  const report = Object.fromEntries(BUCKETS.map((bucket) => [bucket.name, 0]));
67	  for (const invoice of invoices) {
68	    if (invoice.currency !== currency) continue;
69	    const balance = balanceOf(invoice);
70	    if (balance <= 0) continue;
71	    report[bucketFor(daysOverdue(invoice, asOf, termsDays))] += balance;
72	  }
73	  return report;
74	}
75	
76	/** The totals behind a dunning queue, per currency and stage, for the team lead. */
77	export function dunningSummary(queue) {
78	  const summary = {};
79	  for (const { currency, stage, balance } of queue) {
80	    summary[currency] ??= {};
81	    summary[currency][stage] = (summary[currency][stage] ?? 0) + balance;
82	  }
83	  return summary;
84	}
