1	/**
2	 * Revenue by calendar month. A charge is earned over the days it pays for, so a
3	 * line with a service period is spread across the months it touches. A credit
4	 * note counts in the month it was issued.
5	 */
6	
7	import { compareDates, daysBetween, monthKey, parseIsoDate } from '../core/dates.mjs';
8	import { scaleRounded } from '../core/rounding.mjs';
9	import { allocate } from '../invoicing/allocation.mjs';
10	import { daysByMonth } from '../schedule/periods.mjs';
11	
12	function addTo(months, month, amount) {
13	  months.set(month, (months.get(month) ?? 0) + amount);
14	}
15	
16	function spreadLine(months, invoice, line) {
17	  if (line.net === 0) return;
18	  if (!line.period) {
19	    addTo(months, monthKey(invoice.issueDate), line.net);
20	    return;
21	  }
22	  const split = daysByMonth(line.period);
23	  const parts = allocate(line.net, split.map(({ days }) => days));
24	  split.forEach(({ month }, position) => addTo(months, month, parts[position]));
25	}
26	
27	/**
28	 * Revenue per month in one currency, in date order.
29	 *
30	 * @returns {{month: string, amount: number}[]}
31	 */
32	export function revenueByMonth({ invoices, notes, currency }) {
33	  const months = new Map();
34	  for (const invoice of invoices.filter((entry) => entry.currency === currency)) {
35	    for (const line of invoice.lines) spreadLine(months, invoice, line);
36	  }
37	  for (const note of notes) {
38	    addTo(months, monthKey(note.date), -note.netTotal);
39	  }
40	  return [...months]
41	    .map(([month, amount]) => ({ month, amount }))
42	    .sort((a, b) => a.month.localeCompare(b.month));
43	}
44	
45	/**
46	 * Deferred revenue: what has been invoiced for time that has not happened yet, as
47	 * of a date. Only lines with a service period count. A line whose period is over
48	 * has nothing left to defer, and one that has not started defers all of it.
49	 */
50	export function deferredRevenue({ invoices, currency, asOf }) {
51	  parseIsoDate(asOf);
52	  let total = 0;
53	  for (const invoice of invoices) {
54	    if (invoice.currency !== currency) continue;
55	    for (const line of invoice.lines) {
56	      if (!line.period || line.net === 0) continue;
57	      total += deferredPart(line, asOf);
58	    }
59	  }
60	  return total;
61	}
62	
63	function deferredPart(line, asOf) {
64	  const { start, end } = line.period;
65	  if (compareDates(asOf, end) >= 0) return 0;
66	  if (compareDates(asOf, start) < 0) return line.net;
67	  return scaleRounded(line.net, daysBetween(asOf, end), daysBetween(start, end));
68	}
69	
70	/** Revenue rows per quarter, from the rows of revenueByMonth. */
71	export function revenueByQuarter(rows) {
72	  const quarters = new Map();
73	  for (const { month, amount } of rows) {
74	    const [year, monthNumber] = month.split('-').map(Number);
75	    const key = `${year}-Q${Math.ceil(monthNumber / 3)}`;
76	    quarters.set(key, (quarters.get(key) ?? 0) + amount);
77	  }
78	  return [...quarters]
79	    .map(([quarter, amount]) => ({ quarter, amount }))
80	    .sort((a, b) => a.quarter.localeCompare(b.quarter));
81	}
