1	/**
2	 * Looking ahead: recurring revenue from active subscriptions and what the next
3	 * renewals should bring in, both at the terms that will apply.
4	 */
5	
6	import { seatCharge } from '../catalog/plans.mjs';
7	import { divideRounded, scaleRounded } from '../core/rounding.mjs';
8	import { periodAt } from '../schedule/periods.mjs';
9	import { couponFor } from '../subscriptions/renewal.mjs';
10	
11	const BASIS_POINTS = 10_000;
12	
13	function afterCoupon(record, amount, periodIndex) {
14	  const coupon = couponFor(record, periodIndex);
15	  if (!coupon) return amount;
16	  return amount - scaleRounded(amount, coupon.percentBps, BASIS_POINTS);
17	}
18	
19	function termsAtRenewal(record) {
20	  const { scheduled } = record;
21	  return {
22	    plan: scheduled?.plan ?? record.plan,
23	    seats: scheduled?.seats ?? record.seats,
24	  };
25	}
26	
27	/** Recurring revenue per month across active subscriptions in one currency. */
28	export function monthlyRecurringRevenue(records, currency) {
29	  let total = 0;
30	  for (const record of records) {
31	    if (record.status !== 'active' || record.currency !== currency) continue;
32	    const charge = seatCharge(record.plan, currency, record.seats);
33	    const net = afterCoupon(record, charge, record.period.index);
34	    total += divideRounded(net, record.intervalMonths);
35	  }
36	  return total;
37	}
38	
39	/** The next renewal of each active subscription that is not set to cancel. */
40	export function renewalForecast(records, currency) {
41	  const rows = [];
42	  for (const record of records) {
43	    if (record.status !== 'active' || record.currency !== currency) continue;
44	    if (record.scheduled?.cancel) continue;
45	    const index = record.period.index + 1;
46	    const { plan, seats } = termsAtRenewal(record);
47	    const charge = seatCharge(plan, currency, seats);
48	    rows.push({
49	      subscriptionId: record.id,
50	      renewsOn: periodAt(record.anchor, record.intervalMonths, index).start,
51	      amount: afterCoupon(record, charge, index),
52	    });
53	  }
54	  return rows.sort((a, b) => a.renewsOn.localeCompare(b.renewsOn));
55	}
56	
57	/**
58	 * Subscriptions that started or ended in a month, for the board pack. Figures are
59	 * counts, so currency does not come into it.
60	 */
61	export function subscriberMovement(records, month) {
62	  let started = 0;
63	  let ended = 0;
64	  let active = 0;
65	  for (const record of records) {
66	    if (record.anchor.slice(0, 7) === month) started += 1;
67	    if (record.endedOn && record.endedOn.slice(0, 7) === month) ended += 1;
68	    if (record.status === 'active') active += 1;
69	  }
70	  return { month, started, ended, active };
71	}
72	
73	/**
74	 * Churn over a month: subscriptions that ended, as basis points of the ones active
75	 * when it began. Returns 0 when there were none to lose.
76	 */
77	export function monthlyChurnBps(records, month) {
78	  const startOfMonth = `${month}-01`;
79	  let atStart = 0;
80	  let lost = 0;
81	  for (const record of records) {
82	    if (record.anchor >= startOfMonth) continue;
83	    if (record.endedOn && record.endedOn < startOfMonth) continue;
84	    atStart += 1;
85	    if (record.endedOn && record.endedOn.slice(0, 7) === month) lost += 1;
86	  }
87	  return atStart === 0 ? 0 : divideRounded(lost * 10_000, atStart);
88	}
89	
90	/** How many active subscriptions are on each plan. */
91	export function subscribersByPlan(records) {
92	  const counts = new Map();
93	  for (const record of records) {
94	    if (record.status !== 'active') continue;
95	    counts.set(record.plan.code, (counts.get(record.plan.code) ?? 0) + 1);
96	  }
97	  return Object.fromEntries([...counts].sort(([a], [b]) => a.localeCompare(b)));
98	}
