1	/**
2	 * Exports: spreadsheets for the finance team, with amounts in decimal form, and a
3	 * JSON snapshot of the whole book for the nightly backup.
4	 */
5	
6	function decimal(amount) {
7	  return (amount / 100).toFixed(2);
8	}
9	
10	function quote(value) {
11	  const text = String(value ?? '');
12	  return /[",\n]/.test(text) ? `"${text.replaceAll('"', '""')}"` : text;
13	}
14	
15	function toCsv(header, rows) {
16	  return `${[header, ...rows].map((row) => row.map(quote).join(',')).join('\n')}\n`;
17	}
18	
19	export function invoicesCsv(invoices) {
20	  const header = ['number', 'customer', 'currency', 'issued', 'net', 'tax', 'total', 'due'];
21	  const rows = invoices.map((invoice) => [
22	    invoice.number,
23	    invoice.customerId,
24	    invoice.currency,
25	    invoice.issueDate,
26	    decimal(invoice.netTotal, invoice.currency),
27	    decimal(invoice.taxTotal, invoice.currency),
28	    decimal(invoice.total, invoice.currency),
29	    decimal(invoice.amountDue, invoice.currency),
30	  ]);
31	  return toCsv(header, rows);
32	}
33	
34	export function creditNotesCsv(notes) {
35	  const header = ['number', 'invoice', 'currency', 'issued', 'net', 'tax', 'total'];
36	  const rows = notes.map((note) => [
37	    note.number,
38	    note.invoiceNumber,
39	    note.currency,
40	    note.date,
41	    decimal(note.netTotal, note.currency),
42	    decimal(note.taxTotal, note.currency),
43	    decimal(note.total, note.currency),
44	  ]);
45	  return toCsv(header, rows);
46	}
47	
48	function plain(value) {
49	  return JSON.parse(JSON.stringify(value));
50	}
51	
52	/**
53	 * Everything in the book as one JSON document, in a stable order, with plans and
54	 * coupons reduced to their codes so the file does not repeat the catalog.
55	 */
56	export function bookSnapshot({ subscriptions, invoices, notes, settlements, takenOn }) {
57	  const compactRecord = (record) => ({
58	    ...plain(record),
59	    plan: record.plan.code,
60	    coupon: record.coupon ? record.coupon.code : null,
61	    scheduled: record.scheduled
62	      ? {
63	          ...plain(record.scheduled),
64	          plan: record.scheduled.plan ? record.scheduled.plan.code : undefined,
65	        }
66	      : null,
67	  });
68	  const byKey = (key) => (a, b) => String(a[key]).localeCompare(String(b[key]));
69	  return JSON.stringify(
70	    {
71	      takenOn,
72	      subscriptions: subscriptions.map(compactRecord).sort(byKey('id')),
73	      invoices: plain(invoices).sort(byKey('number')),
74	      creditNotes: plain(notes).sort(byKey('number')),
75	      settlements: plain(settlements),
76	    },
77	    null,
78	    2,
79	  );
80	}
81	
82	/** Monthly revenue for one currency. */
83	export function revenueCsv(rows, currency) {
84	  const header = ['month', 'currency', 'revenue'];
85	  const body = rows.map(({ month, amount }) => [month, currency, decimal(amount, currency)]);
86	  return toCsv(header, body);
87	}
88	
89	/** The journal, one row per leg, for the accounting system's import. */
90	export function journalCsv(entries) {
91	  const header = ['date', 'reference', 'currency', 'account', 'debit', 'credit'];
92	  const body = [];
93	  for (const { date, reference, currency, legs } of entries) {
94	    for (const { account, amount } of legs) {
95	      const debit = amount > 0 ? decimal(amount, currency) : '';
96	      const credit = amount < 0 ? decimal(-amount, currency) : '';
97	      body.push([date, reference, currency, account, debit, credit]);
98	    }
99	  }
100	  return toCsv(header, body);
101	}
102	
103	/** The instalment plans agreed with customers, for the collections team. */
104	export function instalmentsCsv(plan, currency) {
105	  const header = ['number', 'due', 'currency', 'amount'];
106	  const body = plan.map(({ number, due, amount }) => [number, due, currency, decimal(amount, currency)]);
107	  return toCsv(header, body);
108	}
