42	export function paymentReminder({ customer, invoice, balance, stage }) {
43	  const { currency, number } = invoice;
44	  const subjects = {
45	    overdue: `Invoice ${number} is overdue`,
46	    'first-reminder': `Reminder: invoice ${number} is unpaid`,
