1	/**
2	 * Plans and seat pricing. Prices are written the way a pricing page writes them,
3	 * as decimal text per currency, and stored as minor units per seat per billing
4	 * interval. A plan can price by flat rate per seat, by graduated tiers, or both
5	 * in different currencies.
6	 *
7	 * With graduated tiers each tier prices the seats that fall inside it, so the
8	 * first ten seats keep their rate when an eleventh is added. `upTo` is the last
9	 * seat priced at that tier's rate. The final tier has `upTo: null` and takes every
10	 * seat above the previous one.
11	 */
12	
13	import { parseAmount } from '../core/money.mjs';
14	import { assertNonEmptyArray, assertPositiveInteger, assertText } from '../core/validate.mjs';
15	
16	function assertTierOrder(tiers) {
17	  tiers.forEach((tier, position) => {
18	    const isLast = position === tiers.length - 1;
19	    if (isLast && tier.upTo !== null) {
20	      throw new RangeError('The last price tier must be open-ended (upTo: null)');
21	    }
22	    if (!isLast) {
23	      assertPositiveInteger(tier.upTo, 'Tier upTo');
24	      if (position > 0 && tier.upTo <= tiers[position - 1].upTo) {
25	        throw new RangeError('Price tiers must rise');
26	      }
27	    }
28	  });
29	}
30	
31	/** Parses tiers written as { upTo, unit: "10.00" } into minor units. */
32	export function parseTiers(rawTiers, currency) {
33	  assertNonEmptyArray(rawTiers, 'Price tiers');
34	  const tiers = rawTiers.map(({ upTo = null, unit }) => ({
35	    upTo,
36	    unitAmount: parseAmount(unit, currency),
37	  }));
38	  assertTierOrder(tiers);
39	  return Object.freeze(tiers.map((tier) => Object.freeze(tier)));
40	}
41	
42	/** What `seats` seats cost across the tiers. */
43	export function graduatedAmount(tiers, seats) {
44	  assertPositiveInteger(seats, 'seats');
45	  let total = 0;
46	  let priced = 0;
47	  for (const tier of tiers) {
48	    const ceiling = tier.upTo === null ? seats : Math.min(seats, tier.upTo);
49	    const inTier = Math.max(ceiling - priced, 0);
50	    total += inTier * tier.unitAmount;
51	    priced += inTier;
52	    if (priced === seats) break;
53	  }
54	  return total;
55	}
56	
57	/** The rate paid for the seat at a given position, for showing on quotes. */
58	export function rateForSeat(tiers, seat) {
59	  assertPositiveInteger(seat, 'seat');
60	  const tier = tiers.find((candidate) => candidate.upTo === null || seat <= candidate.upTo);
61	  return tier.unitAmount;
62	}
63	
64	/**
65	 * definePlan({
66	 *   code: 'team',
67	 *   name: 'Team',
68	 *   prices: { USD: '19.99', JPY: '2900' },
69	 *   tiers: { EUR: [{ upTo: 10, unit: '10.00' }, { upTo: null, unit: '8.00' }] },
70	 * })
71	 */
72	export function definePlan({ code, name, prices = {}, tiers = {} }) {
73	  assertText(code, 'Plan code');
74	  const minorPrices = {};
75	  for (const [currency, text] of Object.entries(prices)) {
76	    const amount = parseAmount(text, currency);
77	    if (amount < 0) throw new RangeError(`Plan ${code} has a negative ${currency} price`);
78	    minorPrices[currency] = amount;
79	  }
80	  const parsedTiers = {};
81	  for (const [currency, raw] of Object.entries(tiers)) {
82	    parsedTiers[currency] = parseTiers(raw, currency);
83	  }
84	  if (Object.keys(minorPrices).length + Object.keys(parsedTiers).length === 0) {
85	    throw new RangeError(`Plan ${code} has no prices`);
86	  }
87	  return Object.freeze({
88	    code,
89	    name: name ?? code,
90	    prices: Object.freeze(minorPrices),
91	    tiers: Object.freeze(parsedTiers),
92	  });
93	}
94	
95	export function sellsIn(plan, currency) {
96	  return Object.hasOwn(plan.prices, currency) || Object.hasOwn(plan.tiers, currency);
97	}
98	
99	/** A plan's flat price per seat per interval, in minor units of `currency`. */
100	export function priceOf(plan, currency) {
101	  if (!Object.hasOwn(plan.prices, currency)) {
102	    throw new RangeError(`Plan ${plan.code} has no flat price in ${currency}`);
103	  }
104	  return plan.prices[currency];
105	}
106	
107	/** What `seats` seats cost for one whole billing interval. */
108	export function seatCharge(plan, currency, seats) {
109	  assertPositiveInteger(seats, 'seats');
110	  if (Object.hasOwn(plan.tiers, currency)) return graduatedAmount(plan.tiers[currency], seats);
111	  return priceOf(plan, currency) * seats;
112	}
113	
114	/**
115	 * How a seat count is priced, tier by tier, for quotes and the pricing page:
116	 * [{ seats: 10, unitAmount: 1000, amount: 10000 }, { seats: 2, ... }]
117	 */
118	export function seatBreakdown(plan, currency, seats) {
119	  assertPositiveInteger(seats, 'seats');
120	  if (!Object.hasOwn(plan.tiers, currency)) {
121	    const unitAmount = priceOf(plan, currency);
122	    return [{ seats, unitAmount, amount: unitAmount * seats }];
123	  }
124	  const rows = [];
125	  let priced = 0;
126	  for (const tier of plan.tiers[currency]) {
127	    if (priced === seats) break;
128	    const ceiling = tier.upTo === null ? seats : Math.min(seats, tier.upTo);
129	    const inTier = Math.max(ceiling - priced, 0);
130	    if (inTier > 0) {
131	      rows.push({ seats: inTier, unitAmount: tier.unitAmount, amount: inTier * tier.unitAmount });
132	    }
133	    priced += inTier;
134	  }
135	  return rows;
136	}
137	
138	/** The cheapest plan in a list for a seat count, for upgrade suggestions. */
139	export function cheapestPlanFor(plans, currency, seats) {
140	  const candidates = plans.filter((plan) => sellsIn(plan, currency));
141	  if (candidates.length === 0) return null;
142	  return candidates.reduce((best, plan) =>
143	    seatCharge(plan, currency, seats) < seatCharge(best, currency, seats) ? plan : best,
144	  );
145	}
