1	/**
2	 * Customer details: who gets billed, where the documents go, and whether their
3	 * invoices are taxed. A business with a valid tax number in another EU country
4	 * buys under reverse charge, so we bill them with no tax.
5	 */
6	
7	import { parseIsoDate } from '../core/dates.mjs';
8	import { UnknownRecordError, assertText } from '../core/validate.mjs';
9	
10	const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
11	
12	// The shape of a VAT number in each country we have customers in. This only
13	// catches typing mistakes. Whether a number is live is checked elsewhere.
14	const TAX_NUMBER_FORMATS = Object.freeze({
15	  AT: /^ATU\d{8}$/,
16	  BE: /^BE0\d{9}$/,
17	  DE: /^DE\d{9}$/,
18	  ES: /^ES[A-Z0-9]\d{7}[A-Z0-9]$/,
19	  FR: /^FR[A-Z0-9]{2}\d{9}$/,
20	  IE: /^IE\d[A-Z0-9]\d{5}[A-Z]{1,2}$/,
21	  IT: /^IT\d{11}$/,
22	  NL: /^NL\d{9}B\d{2}$/,
23	  SE: /^SE\d{12}$/,
24	});
25	
26	/** The tax region a tax number belongs to, or null if it is not one we know. */
27	export function taxNumberRegion(taxNumber) {
28	  const region = String(taxNumber).slice(0, 2);
29	  const format = TAX_NUMBER_FORMATS[region];
30	  return format && format.test(taxNumber) ? region : null;
31	}
32	
33	function normalizeAddress(address) {
34	  if (!address) return null;
35	  const { line1, line2 = '', city, postalCode = '', country } = address;
36	  assertText(line1, 'Address line 1');
37	  assertText(city, 'City');
38	  assertText(country, 'Country');
39	  return Object.freeze({ line1, line2, city, postalCode, country });
40	}
41	
42	function normalizeCustomer(input) {
43	  const { id, name, email = null, address = null, taxNumber = null, taxNumberCheckedOn = null } = input;
44	  assertText(id, 'Customer id');
45	  assertText(name, 'Customer name');
46	  if (email !== null && !EMAIL.test(email)) throw new RangeError(`Not an email address: ${email}`);
47	  if (taxNumber !== null && taxNumberRegion(taxNumber) === null) {
48	    throw new RangeError(`Not a tax number we recognise: ${taxNumber}`);
49	  }
50	  if (taxNumberCheckedOn !== null) parseIsoDate(taxNumberCheckedOn);
51	  return Object.freeze({
52	    id,
53	    name,
54	    email,
55	    address: normalizeAddress(address),
56	    taxNumber,
57	    taxNumberCheckedOn,
58	  });
59	}
60	
61	/**
62	 * Whether invoices to this customer in `region` go out with no tax: they hold a
63	 * checked tax number from that region, and it is not the seller's own.
64	 */
65	export function isReverseCharge(customer, region, sellerRegion) {
66	  if (!customer || !customer.taxNumber || !customer.taxNumberCheckedOn) return false;
67	  if (!sellerRegion || region === sellerRegion) return false;
68	  return taxNumberRegion(customer.taxNumber) === region;
69	}
70	
71	/** The address block for documents, as lines of text. */
72	export function addressLines(customer) {
73	  const lines = [customer.name];
74	  const { address } = customer;
75	  if (address) {
76	    lines.push(address.line1);
77	    if (address.line2) lines.push(address.line2);
78	    lines.push(`${address.postalCode} ${address.city}`.trim(), address.country);
79	  }
80	  if (customer.taxNumber) lines.push(`Tax number ${customer.taxNumber}`);
81	  return lines;
82	}
83	
84	export function createCustomerRegistry() {
85	  const customers = new Map();
86	  return {
87	    add(input) {
88	      const customer = normalizeCustomer(input);
89	      if (customers.has(customer.id)) throw new RangeError(`Customer ${customer.id} already exists`);
90	      customers.set(customer.id, customer);
91	      return customer;
92	    },
93	    update(id, changes) {
94	      const current = customers.get(id);
95	      if (!current) throw new UnknownRecordError('customer', id);
96	      const customer = normalizeCustomer({ ...current, ...changes, id });
97	      customers.set(id, customer);
98	      return customer;
99	    },
100	    find: (id) => customers.get(id) ?? null,
101	    get(id) {
102	      const customer = customers.get(id);
103	      if (!customer) throw new UnknownRecordError('customer', id);
104	      return customer;
105	    },
106	    all: () => [...customers.values()],
107	  };
108	}
109	
110	/** The block of text at the top of a document sent to a customer. */
111	export function documentHeader(customer, documentNumber) {
112	  return [...addressLines(customer), '', `Document ${documentNumber}`].join('\n');
113	}
114	
115	/** Customers whose tax number has not been checked since a date. */
116	export function taxNumbersToRecheck(customers, since) {
117	  parseIsoDate(since);
118	  return customers
119	    .filter((customer) => customer.taxNumber)
120	    .filter((customer) => !customer.taxNumberCheckedOn || customer.taxNumberCheckedOn < since)
121	    .map((customer) => customer.id);
122	}
