/**
 * Splits an integer amount between lines in proportion to their weights, so
 * that the parts add up to the amount exactly.
 */

import { assertMinorUnits } from '../core/money.mjs';

function assertWeights(weights) {
  if (!Array.isArray(weights) || weights.length === 0) {
    throw new RangeError('allocate needs at least one weight');
  }
  for (const weight of weights) {
    if (!Number.isSafeInteger(weight) || weight < 0) {
      throw new RangeError(`Weights must be non-negative integers, got ${weight}`);
    }
  }
}

/**
 * allocate(amount, weights) returns one integer per weight. The amount may be
 * negative, and splitting it gives the mirror image of splitting its positive.
 * At least one weight has to be positive.
 *
 * Every part is its exact share rounded down, and the units left over go one
 * each to the lines with the largest remainders (the earlier line on a tie).
 * Lines with no weight get nothing.
 */
export function allocate(amount, weights) {
  assertMinorUnits(amount);
  assertWeights(weights);
  const shares = weights.map(BigInt);
  const totalWeight = shares.reduce((sum, weight) => sum + weight, 0n);
  if (totalWeight === 0n) {
    throw new RangeError('allocate needs at least one positive weight');
  }

  const magnitude = BigInt(Math.abs(amount));
  const floors = shares.map((weight) => (magnitude * weight) / totalWeight);
  const remainders = shares.map((weight) => (magnitude * weight) % totalWeight);
  let spare = Number(magnitude - floors.reduce((sum, part) => sum + part, 0n));

  const order = weights
    .map((_, position) => position)
    .filter((position) => shares[position] > 0n)
    .sort((a, b) => {
      if (remainders[a] === remainders[b]) return a - b;
      return remainders[a] > remainders[b] ? -1 : 1;
    });
  const parts = floors.map(Number);
  for (const position of order) {
    if (spare === 0) break;
    parts[position] += 1;
    spare -= 1;
  }
  return parts.map((part) => (amount < 0 && part !== 0 ? -part : part));
}

