import assert from 'node:assert/strict';
import test from 'node:test';

import {
  allocate,
  billingPeriods,
  buildInvoice,
  createBook,
  createCatalog,
  defineCoupon,
  definePlan,
  defineTaxTable,
  formatAmount,
  parseAmount,
  periodAt,
  planChangeAmounts,
  settleCreditNote,
  sumAmounts,
} from '../src/index.mjs';
import { makeBook, subscribeTo } from './support/world.mjs';

// A small deterministic generator, so failures can be reproduced.
function random(seed) {
  let state = seed;
  return (limit) => {
    state = (state * 1_103_515_245 + 12_345) % 2_147_483_648;
    return state % limit;
  };
}

test('a month-end anchor keeps its day after a short month', () => {
  const periods = billingPeriods('2024-01-31', 1, 5);
  assert.deepEqual(
    periods.map((period) => period.end),
    ['2024-02-29', '2024-03-31', '2024-04-30', '2024-05-31', '2024-06-30'],
  );
  assert.equal(periodAt('2023-01-31', 1, 13).start, '2024-02-29');
  assert.equal(periodAt('2024-01-31', 1, 12).start, '2025-01-31');
  assert.equal(periodAt('2023-11-30', 3, 1).end, '2024-05-30');
});

test('renewals follow the anchor through the book', () => {
  const book = makeBook();
  subscribeTo(book, { anchor: '2024-01-31' });
  const issued = book.runRenewals('2024-05-31');
  assert.deepEqual(
    issued.map((invoice) => invoice.issueDate),
    ['2024-02-29', '2024-03-31', '2024-04-30', '2024-05-31'],
  );
});

test('the proration example from the docs comes out as written', () => {
  const period = { start: '2024-02-01', end: '2024-03-01' };
  assert.deepEqual(
    planChangeAmounts({ oldAmount: 2900, newAmount: 5800, period, changeDate: '2024-02-16' }),
    { credit: -1400, charge: 2800, net: 1400 },
  );
  const first = planChangeAmounts({ oldAmount: 2900, newAmount: 5800, period, changeDate: '2024-02-01' });
  assert.deepEqual(first, { credit: -2900, charge: 5800, net: 2900 });

  const catalog = createCatalog([
    definePlan({ code: 'a', prices: { USD: '29.00' } }),
    definePlan({ code: 'b', prices: { USD: '58.00' } }),
  ]);
  const book = createBook({ catalog });
  book.subscribe({ id: 's', customerId: 'c', planCode: 'a', currency: 'USD', anchor: '2024-02-01' });
  const change = book.changePlan('s', { date: '2024-02-16', planCode: 'b' });
  assert.deepEqual(
    change.lines.map((line) => line.amount),
    [-1400, 2800],
  );
  assert.equal(change.lines[0].period.start, '2024-02-16');
});

test('currencies with no or three decimals work end to end', () => {
  assert.equal(parseAmount('2900', 'JPY'), 2900);
  assert.throws(() => parseAmount('29.5', 'JPY'), RangeError);
  assert.equal(parseAmount('1.250', 'KWD'), 1250);
  assert.equal(parseAmount('1.25', 'KWD'), 1250);
  assert.throws(() => parseAmount('1.2345', 'KWD'), RangeError);
  assert.equal(formatAmount(1250, 'KWD'), 'KWD 1.250');
  assert.equal(formatAmount(-5, 'KWD'), 'KWD -0.005');

  const plan = definePlan({ code: 'p', prices: { JPY: '2900', KWD: '9.500' } });
  const book = createBook({ catalog: createCatalog([plan]) });
  const yen = book.subscribe({ id: 'y', customerId: 'cy', planCode: 'p', currency: 'JPY', anchor: '2024-04-01' });
  assert.equal(yen.total, 2900);
  const dinar = book.subscribe({ id: 'k', customerId: 'ck', planCode: 'p', currency: 'KWD', anchor: '2024-04-01' });
  assert.equal(dinar.total, 9500);
  assert.match(book.statement(yen.number), /^Total: JPY 2,900$/m);
  assert.match(book.statement(dinar.number), /^Total: KWD 9\.500$/m);
  assert.equal(book.invoicesCsv().split('\n')[1], 'INV-0001,cy,JPY,2024-04-01,2900,0,2900,2900');
  assert.equal(book.invoicesCsv().split('\n')[2], 'INV-0002,ck,KWD,2024-04-01,9.500,0.000,9.500,9.500');
});

test('allocate is exact, fair and mirrors for negatives', () => {
  const next = random(7);
  for (let round = 0; round < 500; round += 1) {
    const weights = Array.from({ length: 1 + next(6) }, () => (next(3) === 0 ? 0 : next(1000)));
    if (weights.every((weight) => weight === 0)) weights[0] = 1;
    const amount = next(100_000) - 50_000;
    const parts = allocate(amount, weights);
    const total = weights.reduce((sum, weight) => sum + weight, 0);
    assert.equal(sumAmounts(parts), amount);
    parts.forEach((part, index) => {
      assert.ok(Math.abs(part - (amount * weights[index]) / total) < 1, `${amount} ${weights}`);
      if (weights[index] === 0) assert.equal(part, 0);
    });
    assert.deepEqual(
      allocate(-amount, weights),
      parts.map((part) => (part === 0 ? 0 : -part)),
    );
  }
});

test('invoice lines add up to the totals and each line tax stays close to its exact tax', () => {
  const next = random(11);
  for (let round = 0; round < 300; round += 1) {
    const lines = Array.from({ length: 1 + next(5) }, (_, index) => ({
      description: `Line ${index}`,
      unitAmount: (next(3) === 0 ? -1 : 1) * (next(5000) + 1),
      quantity: 1 + next(3),
      taxRateBps: [0, 700, 2100][next(3)],
    }));
    const discount = next(2) === 0 ? null : { percentBps: next(10_001) };
    let invoice;
    try {
      invoice = buildInvoice({
        number: 'X',
        customerId: 'c',
        currency: 'USD',
        issueDate: '2024-01-01',
        lines,
        discount,
        accountCredit: next(3) === 0 ? next(2000) : 0,
      });
    } catch (error) {
      assert.ok(error instanceof RangeError);
      continue;
    }
    assert.equal(sumAmounts(invoice.lines.map((line) => line.net)), invoice.netTotal);
    assert.equal(sumAmounts(invoice.lines.map((line) => line.tax)), invoice.taxTotal);
    assert.equal(sumAmounts(invoice.lines.map((line) => line.gross)), invoice.total);
    assert.equal(invoice.total, invoice.netTotal + invoice.taxTotal);
    assert.equal(invoice.amountDue, Math.max(invoice.total, 0) - invoice.creditApplied);
    for (const line of invoice.lines) {
      assert.ok(Math.abs(line.tax - (line.net * line.taxRateBps) / 10_000) < 1);
    }
  }
});

test('account credit settles an invoice without changing its tax', () => {
  const book = makeBook();
  book.grantAccountCredit('cus_1', 'USD', { amount: 1000, date: '2024-04-01' });
  const invoice = subscribeTo(book);
  assert.equal(invoice.netTotal, 3000);
  assert.equal(invoice.taxTotal, 600);
  assert.equal(invoice.total, 3600);
  assert.equal(invoice.creditApplied, 1000);
  assert.equal(invoice.amountDue, 2600);
  assert.equal(book.balanceOf(invoice.number), 2600);
  assert.equal(book.revenueByMonth('USD')[0].amount, 3000);
  assert.deepEqual(book.unbalancedJournalEntries(), []);
  assert.deepEqual(book.taxReport('USD', '2024-04'), [{ rateBps: 2000, taxable: 3000, tax: 600 }]);
});

test('credit notes in stages never give back more than was charged', () => {
  const book = makeBook();
  const invoice = book.subscribe({
    id: 'sub_d',
    customerId: 'cus_1',
    planCode: 'team',
    currency: 'USD',
    anchor: '2024-04-01',
    region: 'NL',
    seats: 3,
    couponCode: 'WELCOME',
  });
  assert.equal(invoice.netTotal, 8100);
  book.pay(invoice.number, { amount: invoice.total, date: '2024-04-02' });
  const amounts = [3333, 3333, 1000];
  let credited = 0;
  let taxCredited = 0;
  for (const amount of amounts) {
    const available = book.remainingCreditable(invoice.number)[0];
    const note = book.creditInvoice(invoice.number, {
      date: '2024-04-05',
      lines: [{ lineIndex: 0, amount: Math.min(amount, available) }],
    });
    credited += note.netTotal;
    taxCredited += note.taxTotal;
  }
  assert.throws(() => book.creditInvoice(invoice.number, { date: '2024-04-06', lines: [{ lineIndex: 0, amount: 1 }] }));
  const rest = book.remainingCreditable(invoice.number)[0];
  if (rest > 0) {
    const note = book.creditInvoice(invoice.number, { date: '2024-04-06' });
    credited += note.netTotal;
    taxCredited += note.taxTotal;
  }
  assert.equal(credited, invoice.netTotal);
  assert.equal(taxCredited, invoice.taxTotal);
  assert.equal(book.balanceOf(invoice.number), 0);
  const refunded = sumAmounts(book.notes().map((note) => note.settlement.refunded));
  assert.equal(refunded, invoice.total);
  assert.deepEqual(book.unbalancedJournalEntries(), []);
});

test('a credit note first reduces what is owed, then cash, then the account', () => {
  assert.deepEqual(settleCreditNote(100, { openBalance: 30, cashAvailable: 50 }), {
    againstBalance: 30,
    refunded: 50,
    toAccount: 20,
  });
  assert.deepEqual(settleCreditNote(100, { openBalance: 0, cashAvailable: 500 }), {
    againstBalance: 0,
    refunded: 100,
    toAccount: 0,
  });

  const book = makeBook();
  const invoice = subscribeTo(book);
  book.grantAccountCredit('cus_1', 'USD', { amount: 3600, date: '2024-03-31' });
  const paidByCredit = subscribeTo(book, { id: 'sub_2', anchor: '2024-04-02' });
  assert.equal(paidByCredit.amountDue, 0);
  assert.equal(book.balanceOf(paidByCredit.number), 0);
  const note = book.creditInvoice(paidByCredit.number, { date: '2024-04-05' });
  assert.deepEqual(note.settlement, { againstBalance: 0, refunded: 0, toAccount: 3600 });
  assert.equal(book.accountCredit('cus_1', 'USD'), 3600);
  assert.ok(invoice);
  assert.deepEqual(book.unbalancedJournalEntries(), []);
});

test('a discounted customer who changes plan gets back no more than they paid', () => {
  const catalog = createCatalog(
    [
      definePlan({ code: 'a', prices: { USD: '30.00' } }),
      definePlan({ code: 'b', prices: { USD: '60.00' } }),
    ],
    [defineCoupon({ code: 'HALF', percentBps: 5000, periods: 1 })],
  );
  const book = createBook({ catalog });
  const first = book.subscribe({
    id: 's',
    customerId: 'c',
    planCode: 'a',
    currency: 'USD',
    anchor: '2024-04-01',
    couponCode: 'HALF',
  });
  assert.equal(first.netTotal, 1500);
  const change = book.changePlan('s', { date: '2024-04-16', planCode: 'b' });
  // 15 of 30 days left: half of the 15.00 paid goes back, and the new plan is
  // charged at the discount too, because the coupon covers the whole period.
  assert.equal(change.lines[0].amount, -750);
  assert.equal(change.lines[1].amount, 3000);
  assert.equal(change.lines[1].discount, 1500);
  assert.equal(book.subscription('s').couponUses, 1);
  const cancel = book.cancel('s', { date: '2024-04-20' });
  // The segment paid 15.00 for 15 days; 11 are left.
  assert.equal(cancel.lines[0].amount, -1100);
  const renewal = (() => {
    const other = createBook({ catalog });
    other.subscribe({ id: 's', customerId: 'c', planCode: 'a', currency: 'USD', anchor: '2024-04-01', couponCode: 'HALF' });
    return other.renew('s');
  })();
  assert.equal(renewal.discountTotal, 0);
});

test('a plan change keeps what is scheduled for the next renewal', () => {
  const book = makeBook();
  subscribeTo(book, { seats: 3 });
  book.scheduleForRenewal('sub_1', { seats: 1 });
  book.changePlan('sub_1', { date: '2024-04-10', planCode: 'business' });
  assert.equal(book.subscription('sub_1').scheduled.seats, 1);
  assert.equal(book.renew('sub_1').subtotal, 6000);
});

test('credit lines from a plan change use up what can be credited on the original line', () => {
  const book = makeBook();
  const invoice = subscribeTo(book);
  book.changePlan('sub_1', { date: '2024-04-16', planCode: 'business' });
  const left = book.remainingCreditable(invoice.number)[0];
  assert.ok(left < 3000);
  assert.throws(() =>
    book.creditInvoice(invoice.number, { date: '2024-04-20', lines: [{ lineIndex: 0, amount: left + 1 }] }),
  );
});

